mapper.select:
SELECT al.audit_log_id AS auditLogId, al.actor_user_id AS actorUserId, actor.email AS actorEmail, actor.nickname AS actorNickname, al.action_type AS actionType, al.target_type AS targetType, al.target_id AS targetId, al.ip_hash AS ipHash, CAST(al.before_json AS CHAR) AS beforeJson, CAST(al.after_json AS CHAR) AS afterJson, al.created_at AS createdAt FROM audit_log al LEFT JOIN user_account actor ON actor.user_id = al.actor_user_id WHERE 1 = 1
AND al.action_type = #{actionType}
AND al.target_type = #{targetType}
AND al.actor_user_id = #{actorUserId}
ORDER BY al.created_at DESC, al.audit_log_id DESC LIMIT #{limit}

SELECT operation_log_id AS operationLogId, log_level AS logLevel, event_code AS eventCode, message, CAST(context_json AS CHAR) AS contextJson, created_at AS createdAt FROM operation_log WHERE 1 = 1
AND log_level = #{logLevel}
AND event_code = #{eventCode}
ORDER BY created_at DESC, operation_log_id DESC LIMIT #{limit}
